Lemma goto_facts : forall i c k ps0 j s, CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TGoto j s) -> PSO.kind_of i <> PSO.KDead ->
  exists cj t l g, nth_error G.CPS j = Some cj /\ CC.goto_chk GT.NF c ps0 cj s = true /\ PSO.goto_pair_ok (PSO.kind_of i) (PSO.kind_of j) = true /\
    PSO.pview (CC.cp_know c) = Some t /\ PSO.pview (SR.ps_cells ps0) = Some l /\
    PSO.frame_same (PSO.mkdelta (SR.ps_cells ps0) t l) = true /\ PSO.wptr_ok i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = true /\
    PSO.is_same (PSO.d_size (PSO.mkdelta (SR.ps_cells ps0) t l)) = true /\ PSO.view_ok (CC.cp_nx c) (CC.cp_know c) t = true /\
    PSO.view_ok (CC.cp_nx c) (SR.ps_cells ps0) l = true /\
    (negb (PSO.has_bufbyte (CC.cp_F c)) || PSO.has (SR.ps_cells ps0) (KWord (SA (APC.eadd (PSO.v_size l) (PSO.v_bptr l)) 0) 1 (ELit 0)))%bool = true /\
    PSO.gclass i c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) = Some g /\
    PSO.tgt_ok i j c (SR.ps_cells ps0) t l (PSO.mkdelta (SR.ps_cells ps0) t l) g = true.
