Section GXS.
Context {SCFG_P : ScfgP}.
Variable I : PSOIW.inst.
Local Abbreviation L := (PSOIW.iL I).     Local Abbreviation ar := (PSOIW.iar I).    Local Abbreviation C := (PSOIW.iC I).     Local Abbreviation HI := (PSOIW.iHI I).
Local Abbreviation LBo := (PSOIW.iLBo I). Local Abbreviation FF := (PSOIW.iFF I).    Local Abbreviation LK := (PSOIW.iLK I).   Local Abbreviation A := (PSOIW.iA I).
Local Abbreviation sp := (PSOIW.isp I).   Local Abbreviation P := (PSOIW.iP I).      Local Abbreviation V := (PSOIW.iV I).     Local Abbreviation E := (PSOIW.iE I).     Local Abbreviation B := (PSOIW.iB I).
Local Abbreviation M := (PSOIW.iM I).     Local Abbreviation model := (PSOIW.imodel I). Local Abbreviation g0 := (PSOIW.ig I). Local Abbreviation ps := (PSOIW.ips I).
Local Abbreviation HIok := (PSOIW.iHIok I).
Local Abbreviation E0 := (PSOIW.E0 I).      Local Abbreviation LB := (PSOIW.LB I).
Local Abbreviation WW := (PSOIW.WW I).       Local Abbreviation Cred := (PSOX.Cred I).   Local Abbreviation LBV := (PSOIW.LBV I (PSOIW.ig1 I)).
Local Abbreviation bptrI := (PSOX.bptrI).  Local Abbreviation bcapI := (PSOX.bcapI). Local Abbreviation sbI := (PSOX.sbI). Local Abbreviation scapI := (PSOX.scapI).

Variables (i : nat) (c : CC.cutpoint) (k : nat) (ps0 : SR.post_spec) (j : nat) (s : CC.subst) (cj : CC.cutpoint) (t l : PSO.pv) (g : PSO.gcase).
Local Abbreviation cells := (SR.ps_cells ps0).
Local Abbreviation d := (PSO.mkdelta (SR.ps_cells ps0) t l).
Hypothesis IL : CH2.is_leaf G.CPS G.TAGS i c k ps0 (CC.TGoto j s).
Hypothesis HND : PSO.kind_of i <> PSO.KDead.
Hypothesis Hcj : nth_error G.CPS j = Some cj.
Hypothesis Hgc : CC.goto_chk GT.NF c ps0 cj s = true.
Hypothesis Hpair : PSO.goto_pair_ok (PSO.kind_of i) (PSO.kind_of j) = true.
Hypothesis Ht : PSO.pview (CC.cp_know c) = Some t.
Hypothesis Hl : PSO.pview cells = Some l.
Hypothesis Hfs : PSO.frame_same d = true.
Hypothesis Hwp : PSO.wptr_ok i c cells t l d = true.
Hypothesis Hsz : PSO.is_same (PSO.d_size d) = true.
Hypothesis Hvt : PSO.view_ok (CC.cp_nx c) (CC.cp_know c) t = true.
Hypothesis Hvl : PSO.view_ok (CC.cp_nx c) cells l = true.
Hypothesis Hterm : (negb (PSO.has_bufbyte (CC.cp_F c)) || PSO.has cells (KWord (SA (APC.eadd (PSO.v_size l) (PSO.v_bptr l)) 0) 1 (ELit 0)))%bool = true.
Hypothesis Hg : PSO.gclass i c cells t l d = Some g.
Hypothesis Htgt : PSO.tgt_ok i j c cells t l d g = true.
Variables (Ec : env) (Rc : bvmap 5 word) (El : env) (Rl : bvmap 5 word) (A1 : list (Z * Z)) (Mc : mem) (mc : Model) (Ml : mem) (ml : Model).
Hypothesis HAt : CCA.AtV (hl_segs L) c Ec Rc A1 Mc mc.
Hypothesis HA : AAMB I i Ec A1 Mc mc.
Hypothesis Hag : env_agree (CC.cp_nx c) Ec El.
Hypothesis HLF : CCA.leaf_factsA (hl_segs L) c ps0 El Rl A1 Mc mc Ml ml.
Hypothesis HXI : PSOX.XI I i Ec A1 Mc mc.
Local Abbreviation Ej := (CC.env_over GT.NF s El).

