(* [comment removed for export] *)
Lemma GCLS : match g with
  | PSO.GSame => PSO.morek (PSO.d_more d) = Some true /\ PSO.d_st d = PSO.Same /\ PSO.d_more d = PSO.Same /\ PSO.d_sst d = PSO.Same /\ PSO.d_nst d = PSO.Same /\ PSO.d_done d = PSO.Same
  | PSO.GStop => PSO.morek (PSO.d_more d) = Some false /\ PSO.d_st d <> PSO.Other
  | PSO.GAccept => PSO.morek (PSO.d_more d) = Some false /\ PSO.d_st d = PSO.Lit 29 /\ PSO.tst c cells t = Some 2 /\ PSO.d_done d = PSO.Lit 1
  | PSO.GStep s1 s2 => PSO.morek (PSO.d_more d) = Some true /\ PSO.more1 c cells t l = true /\ PSO.tst c cells t = Some s1 /\
                       PSO.step_ok (PSO.lo_ge cells (EVar LEVELV) 1) s1 s2 = true /\ ((PSO.d_st d = PSO.Same /\ s2 = s1) \/ PSO.d_st d = PSO.Lit s2)
  | PSO.GPop v => PSO.morek (PSO.d_more d) = Some true /\ PSO.d_st d = PSO.Var v /\ PSO.kind_of i = PSO.KPop /\ v = (CC.cp_nx c - APC.NCS - 2)%nat /\
                  PSO.more1 c cells t l = true /\ PSO.d_sst d = PSO.Same /\ PSO.d_nst d = PSO.Same
