(* [comment removed for export] *)
Lemma WIN2 : forall mw ps1 code g1, PSOX.CORE I i Ec Mc mw ps1 code g1 ->
  exists w2, PSOIW.wlo w2 = CL5A.uv El (PSO.v_wptr l) /\ PSOIW.whi w2 = PSOIW.whi mw /\
    match w2 with Some (p, e) => p <= e | None => mw = None end /\
    match PML.ps_win ps with
    | Some (p0, e0) => exists p2, w2 = Some (p2, e0) /\ p0 <= p2 <= e0 /\ PSOIW.wlo (PML.ps_win ps1) <= p2 /\ PML.ps_win ps1 = Some (PSOIW.wlo (PML.ps_win ps1), e0)
    | None => w2 = None /\ PML.ps_win ps1 = None
    end /\
    (PSO.d_adv d <> 1 -> w2 = PML.ps_win ps1) /\
