  Z_to_bv 8 (CL5A.uv El (PSO.v_done l)) = Z_to_bv 8 (PML.b2z done2) ->
  (forall buf2 w2, PML.buf_need (PSOST.ps_upd ps1 st2 sst2 nst2 more2 done2 buf2 w2) <= PML.buf_need ps1) ->
  (code = 0 -> more2 = true -> PML.ps_more ps1 = true /\ (In st2 PMXA.KEY_STATES -> 1 <= PML.ps_level ps1)) ->      (* [comment removed for export] *)
