Lemma WLOOPJ : forall ps2 cT evsT alT cp cp2 tgx,
  PSO.is_loopk (PSO.kind_of j) = true -> PSO.kind_of j <> PSO.KCsl -> PSOX.XCELLS I Ml cp cp2 tgx ->
