Lemma W57 : forall ps1 w2, (PSO.d_adv d <> 1 -> w2 = PML.ps_win ps1) ->
  (PSO.d_adv d = 1 -> PSO.curk (PSO.kind_of i) = false -> w2 = (match PML.ps_win ps1 with Some (p, e) => Some (p + 1, e) | None => None end)) ->
  (PSO.d_adv d = 1 -> PSO.curk (PSO.kind_of i) = false) ->
  w2 = match PML.ps_win ps1 with Some (p, e) => Some (p + Z.max 0 (PSO.d_adv d), e) | None => None end.
