(* [comment removed for export] *)
Lemma WGS_SM : forall w2 cp cp2 tg, PSO.kind_of i = PSO.KSm -> PSO.is_loopk (PSO.kind_of j) = true -> g = PSO.GSame ->
  PSOIW.st0 I <> PML.ST_ACCEPT -> 1 <= PSOIW.wlen I ->
