Lemma WGR_PT : forall pc ps1 mw code g1 w2 cp cp2 tg, PSO.kind_of i = PSO.KPt pc -> PSO.kind_of j = PSO.KRetx -> g = PSO.GSame ->
  PSOX.CORE I i Ec Mc mw ps1 code g1 -> 0 <= code <= 31 -> PSOX.XCELLS I Mc cp cp2 tg -> PSOX.WSIM I i Ec ps1 code cp cp2 tg ->
