(* [comment removed for export] *)
Lemma WACC_H : forall ps1 ps2 g1 g2 cc evs al cp cp2 tg, g = PSO.GAccept -> (PSO.kind_of i = PSO.KH \/ PSO.kind_of i = PSO.KHQ) ->
  PSOX.CORE I i Ec Mc (PML.ps_win ps1) ps1 0 g1 -> PSOX.XCELLS I Mc cp cp2 tg -> PSOX.ATH I cc ps1 0 evs al -> PSOX.MATCH cc ps1 cp cp2 tg -> PSOX.SYNC I evs al ->
  PML.ps_st ps1 = PML.ST_ACCEPT -> PML.ps_more ps1 = true ->
  PML.ps_win ps2 = PML.ps_win ps1 -> PML.ps_level ps2 = PML.ps_level ps1 -> PML.ps_stack ps2 = PML.ps_stack ps1 ->
