(* [comment removed for export] *)
Lemma WSTEP_SRC : forall s1 s2 mw ps1 g1, g = PSO.GStep s1 s2 ->
  PSOX.CORE I i Ec Mc mw ps1 0 g1 -> PML.wf_ps ps1 -> PML.ps_more ps1 = true -> PSOX.WCORE I i Ec Mc ps1 0 ->
  forall sst2 nst2 (done2 : bool) buf2 w2, (PSO.d_done d = PSO.Same -> done2 = PML.ps_done ps1) ->
