(* [comment removed for export] *)
Lemma WPUSH_T : forall s1 s2 ps1 g1 x stk sst2 nst2 (done2 : bool) buf2 w2, g = PSO.GPush s1 s2 -> PSO.kind_of i = PSO.KVpush ->
  PSOX.CORE I i Ec Mc (PML.ps_win ps1) ps1 0 g1 -> PML.ps_more ps1 = true -> PSOX.WCORE I i Ec Mc ps1 0 -> PML.ps_stack ps1 = stk ++ [x] -> x = PML.ps_st ps1 ->
  (PSO.d_done d = PSO.Same -> done2 = PML.ps_done ps1) ->
